package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

public class KeyedObjects2D_getObject_TriageGen2Test {

    private KeyedObjects2D dataset;
    private final String ROW_KEY_1 = "Row1";
    private final String ROW_KEY_2 = "Row2";
    private final String COL_KEY_1 = "Col1";
    private final String COL_KEY_2 = "Col2";
    private final String DATA = "TestData";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
        // Note: Based on the code logic: if (row < 1) throw UnknownKeyException.
        // This implies the first element (index 0) in rowKeys is treated as invalid or 
        // the method expects 1-based indexing logic for rows, even though indexOf is 0-based.
        // To pass the row < 1 check, index must be >= 1.

        // Adding a dummy row at index 0 to satisfy the "row < 1" check if necessary, 
        // but the code actually rejects index 0. 
        // This looks like a potential bug in the source code (row < 1), 
        // but we must test according to the provided logic.

        // We will add keys such that index of ROW_KEY_1 is 1.
        // Since we can't easily inject into the internal list without addObject,
        // we add a dummy row first.
        dataset.addObject("Dummy", "DummyRow", "DummyCol"); 

        // Now index 1 will be ROW_KEY_1
        dataset.addObject(DATA, ROW_KEY_1, COL_KEY_1);
        dataset.addObject("OtherData", ROW_KEY_1, COL_KEY_2);
        dataset.addObject("Row2Data", ROW_KEY_2, COL_KEY_1);
    }

    @Test
    public void testGetObject_NullRowKey() {
        try {
            dataset.getObject(null, COL_KEY_1);
            fail("Expected IllegalArgumentException for null rowKey");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'rowKey' argument.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_NullColumnKey() {
        try {
            dataset.getObject(ROW_KEY_1, null);
            fail("Expected IllegalArgumentException for null columnKey");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'columnKey' argument.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_UnknownRowKey() {
        try {
            dataset.getObject("UnknownRow", COL_KEY_1);
            fail("Expected UnknownKeyException for unknown rowKey");
        } catch (UnknownKeyException e) {
            // The message depends on the toString of the key
            assert(e.getMessage().contains("Row key (UnknownRow) not recognised."));
        }
    }

    @Test
    public void testGetObject_RowIndexZero() {
        // The code says: if (row < 1) throw UnknownKeyException
        // This means the very first row (index 0) is always "Unknown"
        // We use the "DummyRow" added in setUp which is at index 0
        try {
            dataset.getObject("DummyRow", COL_KEY_1);
            fail("Expected UnknownKeyException because index 0 is < 1");
        } catch (UnknownKeyException e) {
            assert(e.getMessage().contains("Row key (DummyRow) not recognised."));
        }
    }

    @Test
    public void testGetObject_UnknownColumnKey() {
        try {
            dataset.getObject(ROW_KEY_1, "UnknownCol");
            fail("Expected UnknownKeyException for unknown columnKey");
        } catch (UnknownKeyException e) {
            assert(e.getMessage().contains("Column key (UnknownCol) not recognised."));
        }
    }

    @Test
    public void testGetObject_Success() {
        Object result = dataset.getObject(ROW_KEY_1, COL_KEY_1);
        assertEquals(DATA, result);
    }

    @Test
    public void testGetObject_SuccessSecondColumn() {
        Object result = dataset.getObject(ROW_KEY_1, COL_KEY_2);
        assertEquals("OtherData", result);
    }

    @Test
    public void testGetObject_NullReturnIfColumnMissingInRow() {
        // Add a row that has the column key in the dataset, 
        // but not specifically for this row object.
        // However, the logic uses rowData.getIndex(columnKey). 
        // If the rowData (KeyedObjects) doesn't have the column, it returns -1.

        // We create a new dataset to control state precisely
        KeyedObjects2D cleanDataset = new KeyedObjects2D();
        // Add dummy to satisfy row < 1 check
        cleanDataset.addObject("D", "DR", "DC"); 
        // Add target row at index 1
        cleanDataset.addObject("Val", "R1", "C1");
        // Add a column key to the dataset so getColumnIndex doesn't fail, 
        // but don't add it to R1.
        cleanDataset.addObject("Val2", "R2", "C2");

        // We need to ensure C2 is in the columnKeys list of the dataset
        // But C2 is not in R1's rowData.

        // In this implementation, columnKeys is a list of all columns in the dataset.
        // If R1 doesn't have C2, rowData.getIndex("C2") should return -1.

        // Note: To ensure C2 is in the global columnKeys, we must have added it via addObject.
        // Since addObject was called with C2, C2 is in columnKeys.

        Object result = cleanDataset.getObject("R1", "C2");
        assertNull(result);
    }
}
